<template>
  <template
    v-for="(item, index) in workflowBuilderModel[selectedRowIndex].criteria
      .condition_elements"
    :key="index"
  >
    <div class="row q-pb-xs full-width">
      <div class="col-sm-1 col-md-1 col-lg-1">
        <span class="workflow-count-box q-mr-md">
          {{ index + 1 }}
        </span>
      </div>
      <div class="col-sm-4 col-md-4 col-lg-4 q-pr-md">
        <q-select
          dense
          outlined
          emit-value
          map-options
          clearable
          use-input
          hide-selected
          fill-input
          hide-dropdown-icon
          class="back-white"
          v-model="item.key"
          input-debounce="0"
          :label="$t('select_a_field')"
          :options="filteredDocFields"
          @filter="filterlistEvent"
        >
          <template v-slot:no-option>
            <q-item>
              <q-item-section class="text-grey">
                $t{{ $t('no_data_found') }}
              </q-item-section>
            </q-item>
          </template>
        </q-select>
      </div>
      <div class="col-sm-2 col-md-2 col-lg-2">
        <q-select
          dense
          outlined
          v-model="item.match_type"
          class="back-white"
          :label="$t('please_select')"
          emit-value
          map-options
          :options="operators"
        />
      </div>
      <div class="col-sm-3 col-md-3 col-lg-3">
        <q-select
          dense
          outlined
          v-model="item.match_type"
          class="back-white"
          :label="$t('please_select')"
          emit-value
          map-options
          :options="priority"
        />
      </div>
      <div class="col-sm-5 col-md-5 col-lg-5">
        <q-select
          dense
          outlined
          v-model="item.match_type"
          class="back-white"
          :label="$t('please_select')"
          emit-value
          map-options
          :options="math_operators"
        />
      </div>
      <div class="col-sm-4 col-md-4 col-lg-4 q-pl-md">
        <q-input outlined dense v-model="item.value" class="back-white">
        </q-input>
      </div>
      <div class="col-sm-1 col-md-1 col-lg-1">
        <q-btn
          flat
          color="primary"
          icon="close"
          @click="removeCondition(index)"
        />
      </div>
    </div>
  </template>

  <div class="col-sm-12 col-md-12 col-lg-12">
    <q-btn
      flat
      color="primary"
      icon="add"
      :label="$t('add_row')"
      @click="addRowToCondition(selectedRowIndex)"
    />
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import { useWorkflowBuilderStore } from 'src/store/main';

export default defineComponent({
  name: 'criteriaField',
    components: {},
  data() {
    return {
      criteriaName: ref(''),
    };
  },

  mounted() {
    const docType = this.$route.params.doc_type as string;
    this.loadDocumentDefaultFields(docType);
  },

  methods: {
    filterlistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filteredDocFields = this.docFields;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredDocFields = this.docFields.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    removeCondition(index: number) {
      this.workflowBuilderModel[
        this.selectedRowIndex
      ].criteria.condition_elements.splice(index, 1);
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { loadDocumentDefaultFields, addRowToCondition } =
      workflow_builder_store;
    const { docFields, workflowBuilderModel, selectedRowIndex } = storeToRefs(
      workflow_builder_store,
    );

    return {
      docFields,
      filteredDocFields: ref([] as any),
      selectedRowIndex,
      workflowBuilderModel,

      addRowToCondition,
      loadDocumentDefaultFields,

      operators: [
        {
          value: 'eq',
          label: i18n.t('equal'),
        },
        {
          value: 'ne',
          label: i18n.t('not_equal'),
        },
        {
          value: 'gt',
          label: i18n.t('greater_than'),
        },
        {
          value: 'lt',
          label: i18n.t('less_than'),
        },
      ],
      priority: [
        {
          value: 'high',
          label: i18n.t('high'),
        },
        {
          value: 'medium',
          label: i18n.t('medium'),
        },
        {
          value: 'low',
          label: i18n.t('low'),
        },
      ],
      math_operators: [
        {
          value: '+',
          label: i18n.t('plus'),
        },
        {
          value: '-',
          label: i18n.t('minus'),
        },
        {
          value: '/',
          label: i18n.t('divided'),
        },
        {
          value: '*',
          label: i18n.t('multiplied'),
        },
      ],
    };
  },
});
</script>

<style scoped lang="scss"></style>
