<template>
  <div class="row q-pa-sm back-white">
    <div class="col-sm-12 col-md-12 col-lg-12 q-pa-xs">
      <span class="secondary-c-text">{{
        $t('define_action_for_this_group')
      }}</span>
      <q-icon name="help" class="float-right" size="sm" />
    </div>
  </div>

  <div class="row q-pa-md">
    <div class="col-sm-12 col-md-12 col-lg-12 q-pa-xs">
      {{ $t('action_name') }}*
      <q-icon name="info" size="xs" />
    </div>

    <div class="col-sm-12 col-md-12 col-lg-12 q-pa-xs">
      <q-input
        outlined
        dense
        v-model="workflowBuilderModel[selectedRowIndex].action.name"
        :placeholder="$t('name')"
        class="back-white"
      />
    </div>

    <div class="col-sm-12 col-md-12 col-lg-12 q-pa-xs">
      {{ $t('action_type') }}*
      <q-icon name="info" size="xs" />
    </div>

    <div class="col-sm-12 col-md-12 col-lg-12 q-pa-xs">
      <q-select
        dense
        outlined
        emit-value
        map-options
        clearable
        use-input
        hide-selected
        fill-input
        hide-dropdown-icon
        class="back-white"
        :options="actionTypes"
        v-model="workflowBuilderModel[selectedRowIndex].action.type"
        input-debounce="0"
        :label="$t('action_type')"
        @update:model-value="setActionNode()"
      >
        <template v-slot:no-option>
          <q-item>
            <q-item-section class="text-grey">
              $t{{ $t('no_data_found') }}
            </q-item-section>
          </q-item>
        </template>
      </q-select>
    </div>

    <div
      class="col-sm-12 col-md-12 col-lg-12 q-pa-xs"
      v-if="workflowBuilderModel[selectedRowIndex].action.type"
    >
      <div class="row">
        <div
          v-if="
            workflowBuilderModel[selectedRowIndex].action.type == fieldUpdate
          "
          class="col-sm-12 col-md-12 col-lg-12"
        >
          <div class="row q-pa-xs q-mt-md">
            {{ $t('add_actions') }}
          </div>
          <div class="row q-pa-md workflow-border">
            <div class="col-sm-1 col-md-1 col-lg-1"></div>
            <div class="col-sm-5 col-md-4 col-lg-5 q-pr-sm">
              {{ $t('ai_fields') }}*
            </div>
            <div class="col-sm-5 col-md-4 col-lg-5 q-pl-sm">
              {{ $t('value') }}*
            </div>
            <div class="col-sm-1 col-md-1 col-lg-1"></div>
            <ActionFieldsView />
          </div>
        </div>
        <div class="row full-width" v-else>
          <div class="col-sm-12 col-md-12 col-lg-12 q-pa-xs q-mt-md">
            {{ $t('status') }}
          </div>
          <div class="col-sm-12 col-md-12 col-lg-12">
            <q-select
              outlined
              dense
              v-model="
                workflowBuilderModel[selectedRowIndex].action.action_elements[0]
                  .status
              "
              :options="document_statuses_list"
              emit-value
              map-options
              class="back-white"
              :label="$t('status')"
            >
            </q-select>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import { CONSTANTS } from 'src/constants';
import { useWorkflowBuilderStore, useDropdownStore } from 'src/store/main';
import ActionFieldsView from 'src/pages/WorkflowBuilder/action-fields-view.vue';

export default defineComponent({
  name: 'ActionFieldView',
    components: { ActionFieldsView },
  data() {
    return {
      fieldUpdate: CONSTANTS.field_update,
    };
  },

  mounted: function () {
    this.getDocumentStatuses();
  },
  methods: {
    setActionNode() {
      this.workflowBuilderModel[this.selectedRowIndex].action.action_elements =
        [];
      if (
        this.workflowBuilderModel[this.selectedRowIndex].action.type ==
        this.fieldUpdate
      ) {
        this.addRowToActions(this.selectedRowIndex);
      } else {
        this.addRowToActionsForStatusChange(this.selectedRowIndex);
      }
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { addRowToActions, addRowToActionsForStatusChange } =
      workflow_builder_store;
    const { workflowBuilderModel, selectedRowIndex } = storeToRefs(
      workflow_builder_store,
    );

    const dropdown_store = useDropdownStore();
    const { document_statuses_list } = storeToRefs(dropdown_store);
    const { getDocumentStatuses } = dropdown_store;

    return {
      selectedRowIndex,
      workflowBuilderModel,
      actionTypes: [
        {
          label: 'Update Field',
          value: CONSTANTS.field_update,
        },
        {
          label: 'Change Status',
          value: CONSTANTS.status_change,
        },
      ],

      document_statuses_list,
      getDocumentStatuses,
      addRowToActions,
      addRowToActionsForStatusChange,
    };
  },
});
</script>

<style scoped lang="scss"></style>
