<template>
  <template
    v-for="(item, index) in workflowBuilderModel[selectedRowIndex].action
      .action_elements"
    :key="index + '_' + index"
  >
    <div class="row q-pb-xs full-width">
      <div class="col-sm-1 col-md-1 col-lg-1">
        <span class="workflow-count-box q-mr-md">
          {{ index + 1 }}
        </span>
      </div>
      <div class="col-sm-5 col-md-5 col-lg-5 q-pr-sm">
        <q-select
          dense
          outlined
          emit-value
          map-options
          clearable
          use-input
          hide-selected
          fill-input
          hide-dropdown-icon
          class="back-white"
          v-model="item.field"
          input-debounce="0"
          :label="$t('select_a_field')"
          :options="filteredDocFields"
          @filter="filterlistEvent"
        >
          <template v-slot:no-option>
            <q-item>
              <q-item-section class="text-grey">
                $t{{ $t('no_data_found') }}
              </q-item-section>
            </q-item>
          </template>
        </q-select>
      </div>
      <div class="col-sm-5 col-md-5 col-lg-5 q-pl-sm">
        <q-input outlined dense v-model="item.value" class="back-white" />
      </div>
      <div class="col-sm-1 col-md-1 col-lg-1">
        <q-btn flat color="primary" icon="close" @click="removeAction(index)" />
      </div>
    </div>
  </template>

  <div class="col-sm-12 col-md-12 col-lg-12">
    <q-btn
      flat
      color="primary"
      icon="add"
      :label="$t('add_row')"
      @click="addRowToActions(selectedRowIndex)"
    />
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useWorkflowBuilderStore } from 'src/store/main';

export default defineComponent({
  el: '#app',
    components: {},
  data() {
    return {
      criteriaName: ref(''),
    };
  },

  mounted() {
    this.loadDocumentDefaultFields('INVOICE');
  },
  methods: {
    filterlistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filteredDocFields = this.docFields;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredDocFields = this.docFields.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    removeAction(index: number) {
      this.workflowBuilderModel[
        this.selectedRowIndex
      ].action.action_elements.splice(index, 1);
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { loadDocumentDefaultFields, addRowToActions } =
      workflow_builder_store;
    const { docFields, workflowBuilderModel, selectedRowIndex } = storeToRefs(
      workflow_builder_store,
    );

    return {
      docFields,
      filteredDocFields: ref([] as any),
      selectedRowIndex,
      workflowBuilderModel,

      addRowToActions,
      loadDocumentDefaultFields,
    };
  },
});
</script>

<style scoped lang="scss"></style>
