<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import { $, type dynamicObj } from 'src/pages/assets';
import { workflowApiService } from 'src/services';
import { useWorkflowBuilderStore } from 'src/store/main';
import Action from 'src/pages/WorkflowBuilder/action.vue';
import Criteria from 'src/pages/WorkflowBuilder/criteria.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
export default defineComponent({
  name: 'workflowDesigner',
  mixins: [helperUtil, helperMixin],
  components: {  Loader, SubHeader, Criteria, Action },
  data() {
    return {
      workFlowId: ref(''),
      criteriaValue: ref('after'),
      showAddCriteriaBox: ref(false),
      isConditionContent: ref(true),
    };
  },

  mounted() {
    this.workflowBuilderModel = [];
    this.workFlowId = this.$route.params.id as string;
    if (!this.workFlowId) {
      return;
    }
    this.loadWorkFlowBuilderById();
    this.prepareCriteriaOptions();
  },
  unmounted: function () {
    logInfo('unmounted');
  },

  methods: {
    openAddCriteriadlg() {
      this.showAddCriteriaBox = true;
      this.criteriaValue = 'after';
    },
    createCriteria() {
      let indexTochange = this.selectedRowIndex;
      if (this.criteriaValue == 'after') {
        indexTochange += 1;
      }

      this.addCriteria(indexTochange);
    },

    deleteSelectedCriteria() {
      let isDeleted = this.deleteCriteria(this.selectedRowIndex);

      if (isDeleted) {
        notify.success(this.$t('CRITERIA_DELETED'));
      } else {
        notify.success(this.$t('CRITERIA_VALUE_CLEARED'));
      }
    },

    setSelectionType(type: boolean, index: number) {
      this.isConditionContent = type;
      this.selectedRowIndex = index;
    },
    async loadWorkFlowBuilderById() {
      let response: any;
      try {
        this.showLoading();

        response = await workflowApiService.getWorkflowJson(this.workFlowId);

        if (
          !response ||
          !response.conditions ||
          !response.actions ||
          !response.logic
        ) {
          this.loadDefaultWorkFlowJson();
        } else {
          this.prepareWorkflowBuilderModel(response);
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    prepareWorkflowBuilderModel(response: any) {
      let nodeMap = new Map();
      let actionMap = new Map();
      let conditionMap = new Map();

      for (const data of response.conditions) {
        conditionMap.set(data.id, data);
      }

      for (const data of response.actions) {
        actionMap.set(data.id, data);
      }

      for (const data of response.logic.nodes) {
        if (data.hasOwnProperty('next_step')) {
          continue;
        }
        nodeMap.set(data.id, data);
      }

      let node = response.logic.start;

      let criteriaObj = {
        criteria: conditionMap.get(node.id),
        action: actionMap.get(node.true),
      };

      let nextObjId = node.false;

      this.workflowBuilderModel.push(criteriaObj);

      while (nodeMap.size > 0) {
        node = nodeMap.get(nextObjId);

        criteriaObj = {
          criteria: conditionMap.get(node.id),
          action: actionMap.get(node.true),
        };
        this.workflowBuilderModel.push(criteriaObj);

        nextObjId = node.false;
        nodeMap.delete(node.id);
      }
    },
    validateConditionsNode(condition: any, index: number) {
      let error = false;
      if (!condition.name) {
        error = true;
      }

      for (const node of condition.condition_elements) {
        if (!node.key || !node.match_type || !node.value) {
          this.setSelectionType(true, index);
          error = true;
          break;
        }
      }

      return error;
    },
    validateActionNode(action: any, index: number) {
      let error = false;
      if (!action.name) {
        error = true;
      }

      for (const node of action.action_elements) {
        if (
          (node.hasOwnProperty('field') && !node.field) ||
          (node.hasOwnProperty('value') && !node.value) ||
          (node.hasOwnProperty('status') && !node.status)
        ) {
          this.setSelectionType(false, index);
          error = true;
          break;
        }
      }

      return error;
    },
    saveWorkFlow() {
      if (this.workflowBuilderModel.length == 0) {
        notify.error('No Data found to save');
      }

      let conditions = [] as dynamicObj;
      let actions = [] as dynamicObj;
      let nodes = [] as dynamicObj;
      let start = {} as dynamicObj;

      let nextCriteriaNode = null;
      let nextObjId = null;

      // prepare json for save
      for (const [index, data] of Object.entries(this.workflowBuilderModel)) {
        let criteriaNode = data as any;

        if (
          this.validateConditionsNode(criteriaNode.criteria, +index) ||
          this.validateActionNode(criteriaNode.action, +index)
        ) {
          notify.error(this.$t('MISSING_FIELD'));
          return;
        }
        conditions.push(criteriaNode.criteria);
        actions.push(criteriaNode.action);

        nextCriteriaNode = this.workflowBuilderModel[1 + +index];
        nextObjId = null;

        if (nextCriteriaNode) {
          nextObjId = nextCriteriaNode.criteria.id;
        }

        nodes.push(
          Object.assign(
            {},
            {
              false: nextObjId,
              id: criteriaNode.criteria.id,
              true: criteriaNode.action.id,
            },
          ),
        );

        nodes.push(
          Object.assign(
            {},
            {
              id: criteriaNode.action.id,
              next_step: null,
            },
          ),
        );
      }

      start = nodes[0];
      nodes.splice(0, 1);

      const finalJson = {
        actions: actions,
        conditions: conditions,
        logic: {
          nodes: nodes,
          start: start,
        },
      };

      logInfo(finalJson);

      this.proceedWorkflowSaving(finalJson);
    },
    proceedWorkflowSaving(finalJson: any) {
      let response: any;
      try {
        this.showLoading();

        // Deprecated
        // response = await workflowApiService.saveWorkflowJson(this.workFlowId ,finalJson);
        logInfo(response);

        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    prepareCriteriaOptions() {
      this.criteriaOptions = [
        {
          label: i18n.t('add_criteria_after_current_criteria'),
          value: 'after',
        },
        {
          label: i18n.t('add_criteria_before_current_criteria'),
          value: 'before',
        },
      ];
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { addCriteria, deleteCriteria, loadDefaultWorkFlowJson } =
      workflow_builder_store;
    const { workflowBuilderModel, selectedRowIndex } = storeToRefs(
      workflow_builder_store,
    );

    workflow_builder_store.$reset();

    return {
      selectedRowIndex,
      workflowBuilderModel,

      addCriteria,
      deleteCriteria,
      loadDefaultWorkFlowJson,

      criteriaOptions: ref([] as any),
    };
  },
});
</script>

